WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_trv_avg_time'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '等时间平均速度', 'kp-trv-avg-time', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "等时间平均速度"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心公式：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "算术平均数：(V1+V2)/2。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“某人开车，前 1 小时速度为 40，后 1 小时速度为 60。求平均速度”。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心法则"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "当时间被等分时，这才是我们初中学过的普通的算术平均数。因为每个速度发挥作用的时间一样长。"}]}, {"type": "katexBlock", "attrs": {"content": "V_{平均} = \\frac{V_1 \\times t + V_2 \\times t}{2t} = \\frac{V_1+V_2}{2}"}}]}$$ AS jsonb), NULL, '等时间平均速度的核心考点与实战推导。', category_node.id, CAST('["数量关系", "行程问题", "等时间平均速度"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_trv_avg_time", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
